import { PartOfSpeech, type VocabItem } from '../content/types';

/** One meaning group of a word, e.g. the noun "Bank" (bench). */
export interface DictionaryEntry {
  word: string;
  partOfSpeech: PartOfSpeech;
  /** A gender code defined by the target language pack (e.g. 'm' for German). */
  gender?: string;
  plural?: string;
  /** Pronunciation in IPA, e.g. "/hʊnt/". */
  ipa?: string;
  meanings: string[];
}

/** A bundled dictionary file, generated by tools/build-dictionary.mjs. */
export interface DictionaryData {
  /** Attribution for the data, shown with the dictionary. */
  source: string;
  /** Most common words first; search ranks by this order. */
  entries: DictionaryEntry[];
  /** Lower-case inflected form → indexes into `entries` of the words it is a form of ("bin" → sein). */
  forms: Record<string, number[]>;
}

/** A word found by a search. */
export interface DictionaryResult {
  entry: DictionaryEntry;
  /** The course's own vocab item for this word, with its respelling and example. */
  courseVocab?: VocabItem;
  /** Set when the search matched an inflected form of the word, e.g. "bin" for sein. */
  matchedForm?: string;
}

/** Why a word matched; lower values are shown first. */
enum MatchQuality {
  WORD = 0,
  FORM = 1,
  /** The query is exactly one of the word's first meanings ("go" → gehen: "to go, to walk"). */
  FIRST_MEANING = 2,
  MEANING = 3,
  WORD_PREFIX = 4,
  MEANING_WORD = 5,
}

const MAX_RESULTS = 30;
/** Searching meanings with one letter would match nearly everything. */
const MIN_MEANING_QUERY_LENGTH = 2;

interface IndexedEntry {
  entry: DictionaryEntry;
  courseVocab?: VocabItem;
  /** Spellings the query is compared with, e.g. "für" → ["fur", "fuer"]. */
  keys: string[];
  /** Lower-case meanings for searching in the base language. */
  meanings: string[];
  /** The first meaning's alternatives without articles or notes ("to go, to walk" → ["go", "walk"]). */
  firstCoreMeanings: string[];
  /** The same for every meaning. */
  coreMeanings: string[];
}

/** A dictionary prepared for fast repeated searching. */
export interface DictionaryIndex {
  entries: IndexedEntry[];
  /** Folded inflected form → entry indexes. */
  forms: Map<string, number[]>;
}

/** Lower-cases and removes accents, so "Für" and "fur" compare equal. */
function stripAccents(text: string): string {
  return text
    .toLowerCase()
    .replace(/ß/g, 'ss')
    .normalize('NFD')
    .replace(/\p{Diacritic}/gu, '')
    .trim();
}

/** Lower-cases and spells special characters the way learners type them without a special keyboard (ü → ue). */
function foldCharacters({ text, characterFolds }: { text: string; characterFolds: Record<string, string> }): string {
  let folded = text.toLowerCase().trim();
  Object.entries(characterFolds).forEach(([character, replacement]) => {
    folded = folded.split(character).join(replacement);
  });
  return folded;
}

function spellingKeys({ text, characterFolds }: { text: string; characterFolds: Record<string, string> }): string[] {
  return [...new Set([stripAccents(text), foldCharacters({ text, characterFolds })])];
}

/** "to go (somewhere)" → "go", so "go" finds gehen. */
function coreMeaning(meaning: string): string {
  return meaning
    .replace(/\([^)]*\)/g, '')
    .replace(/^(to|a|an|the) /, '')
    .trim();
}

function coreMeanings(meanings: string[]): string[] {
  return meanings.flatMap((meaning) => meaning.toLowerCase().split(/[,;] /).map(coreMeaning));
}

function containsWord({ text, word }: { text: string; word: string }): boolean {
  let start = text.indexOf(word);
  while (start !== -1) {
    const before = text[start - 1];
    const after = text[start + word.length];
    if ((!before || !/\p{L}/u.test(before)) && (!after || !/\p{L}/u.test(after))) {
      return true;
    }
    start = text.indexOf(word, start + 1);
  }
  return false;
}

function courseVocabEntry(vocab: VocabItem): DictionaryEntry {
  return {
    word: vocab.text,
    partOfSpeech: vocab.partOfSpeech,
    gender: vocab.gender,
    plural: vocab.plural,
    meanings: vocab.translations,
  };
}

/**
 * Prepares a dictionary for searching, merged with the course's own vocab:
 * course words are linked to their dictionary entry (for the respelling and
 * example), and course words the dictionary lacks, such as phrases, are added.
 */
export function buildDictionaryIndex({
  dictionary,
  courseVocab,
  characterFolds,
}: {
  dictionary: DictionaryData;
  courseVocab: VocabItem[];
  characterFolds: Record<string, string>;
}): DictionaryIndex {
  const indexesByWord = new Map<string, number[]>();
  dictionary.entries.forEach((entry, index) => {
    indexesByWord.set(entry.word, [...(indexesByWord.get(entry.word) ?? []), index]);
  });

  const courseVocabByIndex = new Map<number, VocabItem>();
  const courseOnly: VocabItem[] = [];
  courseVocab.forEach((vocab) => {
    const indexes = indexesByWord.get(vocab.text) ?? [];
    const sameKind = indexes.find((index) => dictionary.entries[index].partOfSpeech === vocab.partOfSpeech);
    const match = sameKind ?? indexes[0];
    if (match === undefined) {
      courseOnly.push(vocab);
    } else if (!courseVocabByIndex.has(match)) {
      courseVocabByIndex.set(match, vocab);
    }
  });

  const indexEntry = (entry: DictionaryEntry, courseVocabItem?: VocabItem): IndexedEntry => ({
    entry,
    courseVocab: courseVocabItem,
    keys: spellingKeys({ text: entry.word, characterFolds }),
    meanings: entry.meanings.map((meaning) => meaning.toLowerCase()),
    firstCoreMeanings: coreMeanings(entry.meanings.slice(0, 1)),
    coreMeanings: coreMeanings(entry.meanings),
  });

  // Course-only words go last so dictionary positions (and the form links to them) stay valid.
  const entries = [
    ...dictionary.entries.map((entry, index) => indexEntry(entry, courseVocabByIndex.get(index))),
    ...courseOnly.map((vocab) => indexEntry(courseVocabEntry(vocab), vocab)),
  ];

  const forms = new Map<string, number[]>();
  Object.entries(dictionary.forms).forEach(([form, indexes]) => {
    spellingKeys({ text: form, characterFolds }).forEach((key) => {
      forms.set(key, [...new Set([...(forms.get(key) ?? []), ...indexes])]);
    });
  });
  return { entries, forms };
}

function matchQuality({
  indexed,
  query,
  meaningQuery,
}: {
  indexed: IndexedEntry;
  query: string;
  /** The query as a core meaning, so "to be" compares as "be". */
  meaningQuery: string;
}): MatchQuality | null {
  if (indexed.keys.includes(query)) {
    return MatchQuality.WORD;
  }
  if (query.length >= MIN_MEANING_QUERY_LENGTH) {
    if (indexed.firstCoreMeanings.includes(meaningQuery)) {
      return MatchQuality.FIRST_MEANING;
    }
    if (indexed.coreMeanings.includes(meaningQuery)) {
      return MatchQuality.MEANING;
    }
  }
  if (indexed.keys.some((key) => key.startsWith(query))) {
    return MatchQuality.WORD_PREFIX;
  }
  if (query.length >= MIN_MEANING_QUERY_LENGTH && indexed.meanings.some((meaning) => containsWord({ text: meaning, word: query }))) {
    return MatchQuality.MEANING_WORD;
  }
  return null;
}

/**
 * Finds words by target-language spelling (accents optional, inflected forms
 * like "bin" lead to "sein") or by meaning in the base language. Exact
 * matches come first, then more common words.
 */
export function searchDictionary({ index, query }: { index: DictionaryIndex; query: string }): DictionaryResult[] {
  const normalizedQuery = stripAccents(query);
  if (!normalizedQuery) {
    return [];
  }
  const meaningQuery = coreMeaning(query.toLowerCase().trim());
  const best = new Map<number, { quality: MatchQuality; matchedForm?: string }>();
  index.entries.forEach((indexed, position) => {
    const quality = matchQuality({ indexed, query: normalizedQuery, meaningQuery });
    if (quality !== null) {
      best.set(position, { quality });
    }
  });
  // When the query is a word itself ("Hund"), forms of other words spelled the same are noise.
  const isWord = [...best.values()].some(({ quality }) => quality === MatchQuality.WORD);
  const formMatches = isWord ? [] : (index.forms.get(normalizedQuery) ?? []);
  formMatches.forEach((position) => {
    const current = best.get(position);
    if (!current || current.quality > MatchQuality.FORM) {
      best.set(position, { quality: MatchQuality.FORM, matchedForm: query.trim() });
    }
  });

  return [...best.entries()]
    .sort(([positionA, a], [positionB, b]) => a.quality - b.quality || positionA - positionB)
    .slice(0, MAX_RESULTS)
    .map(([position, { matchedForm }]) => ({
      entry: index.entries[position].entry,
      courseVocab: index.entries[position].courseVocab,
      matchedForm,
    }));
}

/** The entry as a vocab item, so it can be shown and spoken like course words (e.g. "der Hund"). */
export function entryAsVocab(entry: DictionaryEntry): VocabItem {
  return {
    id: `dictionary:${entry.word}`,
    text: entry.word,
    translations: entry.meanings,
    partOfSpeech: entry.partOfSpeech,
    gender: entry.gender,
    plural: entry.plural,
  };
}
